import "@clanker-cleanroom/cursor/register";
import {
  Agent,
  type AgentOptions,
  type AgentRunResult,
  type RegistryOptions,
} from "clanker-cleanroom";

export { load_cursor_skill } from "./load-cursor-skill.js";

export type ExecuteOptions = AgentOptions &
  RegistryOptions & {
    /** Stock short name (`cursor`, `claude`) or registry tag (`cursor:node`). */
    name?: string;
    workspace: string;
  };

export const execute = async (prompt: string, options: ExecuteOptions): Promise<AgentRunResult> => {
  const { workspace, name = "cursor", model, image, packageRoot } = options;

  const agent = new Agent(name, packageRoot !== undefined ? { packageRoot } : {});

  await agent.ensureImage();

  return agent.run({
    workspace,
    prompt,
    ...(model !== undefined ? { model } : {}),
    ...(image !== undefined ? { image } : {}),
  });
};
